;
;COMMANDS:
;
;DELETE line,line
;
MAIN_DELETE:	CALL	MAIN_DLPAIR
MAIN_DELET1:	LD	A,(HL)
	OR	A
	JR	Z,MAIN_WARMNC
	INC	HL
	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	DEC	HL
	DEC	HL
	EX	DE,HL
	SCF
	SBC	HL,BC
	EX	DE,HL
	JR	NC,MAIN_WARMNC
	PUSH	BC
	CALL	MAIN_DEL
	POP	BC
	JR	MAIN_DELET1
;
;LISTO expr
;
MAIN_LISTO:	INC	IY			;SKIP "O"
	CALL	EXPRI
	EXX
	LD	A,L
	LD	(LISTON),A
	JP	CLOOP
;
;LIST
;LIST line
;LIST line,line [IF string]
;LIST ,line
;LIST line,
;
MAIN_LIST:	CP	'O'
	JR	Z,MAIN_LISTO
	LD	C,1
	LD	DE,BUFFER
	CALL	LEXAN2
	LD	(DE),A
	LD	IY,BUFFER
	CALL	MAIN_DLPAIR
	CALL	NXT
	CP	MAIN_TIF			;IF CLAUSE ?
	LD	A,0			;INIT IF-CLAUSE LENGTH
	JR	NZ,MAIN_LISTB
	INC	IY			;SKIP IF
	CALL	NXT			;SKIP SPACES (IF ANY)
	EX	DE,HL
	PUSH	IY
	POP	HL			;HL ADDRESSES IF CLAUSE
	LD	A,MAIN_CR
	PUSH	BC
	LD	BC,256
	CPIR	;LOCATE CR
	LD	A,C
	CPL	;A = SUBSTRING LENGTH
	POP	BC
	EX	DE,HL
MAIN_LISTB:	LD	E,A			;IF-CLAUSE LENGTH
	LD	A,B
	OR	C
	JR	NZ,MAIN_LISTA
	DEC	BC
MAIN_LISTA:	EXX
	LD	IX,LISTON
	LD	E,0			;INDENTATION COUNT
	EXX
	LD	A,20
;
MAIN_LISTC:	PUSH	BC			;SAVE HIGH LINE NUMBER
	PUSH	DE			;SAVE IF-CLAUSE LENGTH
	PUSH	HL			;SAVE PROGRAM POINTER
	EX	AF,AF'
	LD	A,(HL)
	OR	A
	JR	Z,MAIN_WARMNC
;
;CHECK IF PAST TERMINATING LINE NUMBER:
;
	LD	A,E			;A = IF-CLAUSE LENGTH
	INC	HL
	LD	E,(HL)
	INC	HL
	LD	D,(HL)			;DE = LINE NUMBER
	DEC	HL
	DEC	HL
	PUSH	DE			;SAVE LINE NUMBER
	EX	DE,HL
	SCF
	SBC	HL,BC
	EX	DE,HL
	POP	DE			;RESTORE LINE NUMBER
MAIN_WARMNC:	JP	NC,WARM
	LD	C,(HL)			;C = LINE LENGTH + 4
	LD	B,A			;B = IF-CLAUSE LENGTH
;
;CHECK FOR IF CLAUSE:
;
	INC	HL
	INC	HL
	INC	HL			;HL ADDRESSES LINE TEXT
	DEC	C
	DEC	C
	DEC	C
	DEC	C			;C = LINE LENGTH
	PUSH	DE			;SAVE LINE NUMBER
	PUSH	HL			;SAVE LINE ADDRESS
	XOR	A			;A <- 0
	CP	B			;WAS THERE AN IF-CLAUSE
	PUSH	IY
	POP	DE			;DE ADDRESSES IF-CLAUSE
	CALL	NZ,SEARCH		;SEARCH FOR IF CLAUSE
	POP	HL			;RESTORE LINE ADDRESS
	POP	DE			;RESTORE LINE NUMBER
	PUSH	IY
	CALL	Z,MAIN_LISTIT		;LIST IF MATCH
	POP	IY
;
	EX	AF,AF'
	DEC	A
	CALL	LTRAP
	POP	HL			;RESTORE POINTER
	LD	E,(HL)
	LD	D,0
	ADD	HL,DE			;ADDRESS NEXT LINE
	POP	DE			;RESTORE IF-CLAUSE LEN
	POP	BC			;RESTORE HI LINE NUMBER
	JR	MAIN_LISTC
;
;RENUMBER
;RENUMBER start
;RENUMBER start,increment
;RENUMBER ,increment
;
MAIN_RENUM:	CALL	CLEAR			;USES DYNAMIC AREA
	CALL	MAIN_PAIR			;LOAD HL,BC
	EXX
	LD	HL,(PAGE)
	LD	DE,(LOMEM)
MAIN_RENUM1:	LD	A,(HL)			;BUILD TABLE
	OR	A
	JR	Z,MAIN_RENUM2
	INC	HL
	LD	C,(HL)			;OLD LINE NUMBER
	INC	HL
	LD	B,(HL)
	EX	DE,HL
	LD	(HL),C
	INC	HL
	LD	(HL),B
	INC	HL
	EXX
	PUSH	HL
	ADD	HL,BC			;ADD INCREMENT
	JP	C,MAIN_TOOBIG		;"Too big"
	EXX
	POP	BC
	LD	(HL),C
	INC	HL
	LD	(HL),B
	INC	HL
	EX	DE,HL
	DEC	HL
	DEC	HL
	XOR	A
	LD	B,A
	LD	C,(HL)
	ADD	HL,BC			;NEXT LINE
	EX	DE,HL
	PUSH	HL
	INC	H
	SBC	HL,SP
	POP	HL
	EX	DE,HL
	JR	C,MAIN_RENUM1		;CONTINUE
	JP	ERROR			;'No room' (A = 0)
;
MAIN_RENUM2:	EX	DE,HL
	LD	(HL),-1
	INC	HL
	LD	(HL),-1
	LD	DE,(LOMEM)
	EXX
	LD	HL,(PAGE)
MAIN_RENUM3:	LD	C,(HL)
	LD	A,C
	OR	A
	JR	Z,MAIN_WARMNC
	EXX
	EX	DE,HL
	INC	HL
	INC	HL
	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	INC	HL
	PUSH	DE
	EX	DE,HL
	EXX
	POP	DE
	INC	HL
	LD	(HL),E			;NEW LINE NUMBER
	INC	HL
	LD	(HL),D
	INC	HL
	DEC	C
	DEC	C
	DEC	C
	LD	B,0
MAIN_RENUM7:	LD	A,MAIN_TLINO
	CPIR	;SEARCH FOR LINE NUMBER
	JR	NZ,MAIN_RENUM3
	PUSH	BC
	PUSH	HL
	PUSH	HL
	POP	IY
	EXX
	PUSH	HL
	CALL	DECODE			;DECODE LINE NUMBER
	POP	HL
	EXX
	LD	B,H
	LD	C,L
	LD	HL,(LOMEM)
MAIN_RENUM4:	LD	E,(HL)			;CROSS-REFERENCE TABLE
	INC	HL
	LD	D,(HL)
	INC	HL
	EX	DE,HL
	OR	A			;CLEAR CARRY
	SBC	HL,BC
	EX	DE,HL
	LD	E,(HL)			;NEW NUMBER
	INC	HL
	LD	D,(HL)
	INC	HL
	JR	C,MAIN_RENUM4
	EX	DE,HL
	JR	Z,MAIN_RENUM5		;FOUND
	CALL	TELL
	DEFM	'Failed at '
	DEFB	0
	EXX
	PUSH	HL
	EXX
	POP	HL
	CALL	PBCDL
	CALL	CRLF
	JR	MAIN_RENUM6
MAIN_RENUM5:	POP	DE
	PUSH	DE
	DEC	DE
	CALL	MAIN_ENCODE			;RE-WRITE NUMBER
MAIN_RENUM6:	POP	HL
	POP	BC
	JR	MAIN_RENUM7
;
;AUTO
;AUTO start,increment
;AUTO start
;AUTO ,increment
;
MAIN_AUTO:	CALL	MAIN_PAIR
	LD	(AUTONO),HL
	LD	A,C
	LD	(INCREM),A
	JR	MAIN_CLOOP0
;
;BAD
;NEW
;
MAIN_BAD:	CALL	TELL			;"Bad program'
	DEFB	13H
	DEFM	'program'
	DEFB	MAIN_CR
	DEFB	MAIN_LF
	DEFB	0
MAIN_NEW:	CALL	MAIN_NEWIT
	JR	MAIN_CLOOP0
;
;LOAD filename
;
MAIN_LOAD:	CALL	EXPRS			;GET FILENAME
	LD	A,MAIN_CR
	LD	(DE),A
	CALL	LOAD0
	CALL	CLEAR
	JR	MAIN_WARM0
;
;OLD
;
MAIN_OLD:	LD	HL,(PAGE)
	PUSH	HL
	INC	HL
	INC	HL
	INC	HL
	LD	BC,252
	LD	A,MAIN_CR
	CPIR
	JR	NZ,MAIN_BAD
	LD	A,L
	POP	HL
	LD	(HL),A
	CALL	MAIN_CLEAN
MAIN_CLOOP0:	JP	CLOOP
;
;SAVE filename
;
MAIN_SAVE:	CALL	EXPRS			;FILENAME
	LD	A,MAIN_CR
	LD	(DE),A
	LD	DE,(PAGE)
	CALL	GETTOP
	OR	A
	SBC	HL,DE
	LD	B,H			;LENGTH OF PROGRAM
	LD	C,L
	LD	HL,ACCS
	CALL	OSSAVE
MAIN_WARM0:	JP	WARM
;
;ERROR
;N.B. CARE NEEDED BECAUSE SP MAY NOT BE VALID (E.G. ABOVE HIMEM) 
;
ERROR:	LD	HL,MAIN_ERRWDS
	LD	C,A
	OR	A
	JR	Z,MAIN_ERROR1
	LD	B,A			;ERROR NUMBER
	XOR	A
MAIN_ERROR0:	CP	(HL)
	INC	HL
	JR	NZ,MAIN_ERROR0
	DJNZ	MAIN_ERROR0
	JR	MAIN_ERROR1			;MUST NOT PUSH HL HERE
;
EXTERR:	POP	HL
	LD	C,A
MAIN_ERROR1:	LD	(ERRTXT),HL
	LD	HL,(ONERSP)
	LD	A,H
	OR	L
	LD	SP,(HIMEM)		;MUST SET SP BEFORE 'CALL'
	JR	Z,MAIN_ERROR4
	LD	SP,HL
MAIN_ERROR4:	LD	A,C			;ERROR NUMBER
	CALL	SETLIN			;SP IS SET NOW
	LD	(ERR),A
	LD	(ERL),HL
	OR	A
	JR	Z,MAIN_ERROR2		;'FATAL' ERROR
	LD	HL,(ERRTRP)
	LD	A,H
	OR	L
	PUSH	HL
	POP	IY
	JP	NZ,XEQ			;ERROR TRAPPED
MAIN_ERROR2:	LD	SP,(HIMEM)
	SBC	HL,HL
	LD	(AUTONO),HL
	LD	(TRACEN),HL		;CANCEL TRACE
	CALL	RESET			;RESET OPSYS
	CALL	CRLF
	CALL	REPORT			;MESSAGE
	LD	HL,(ERL)
	CALL	SAYLN
	LD	E,0
	CALL	C,OSSHUT		;CLOSE ALL FILES
	CALL	CRLF
	JR	MAIN_CLOOP0
;
;SUBROUTINES:
;
;
;LEX - SEARCH FOR KEYWORDS
;   Inputs: HL = start of keyword table
;           IY = start of match text
;  Outputs: If found, Z-flag set, A=token.
;           If not found, Z-flag reset, A=(IY).
;           IY updated (if NZ, IY unchanged).
; Destroys: A,B,H,L,IY,F
;
MAIN_LEX:	LD	HL,KEYWDS
MAIN_LEX0:	LD	A,(IY)
	LD	B,(HL)
	INC	HL
	CP	(HL)
	JR	Z,MAIN_LEX2
	RET	C			;FAIL EXIT
MAIN_LEX1:	INC	HL
	LD	A,(HL)
	CP	160
	JP	PE,MAIN_LEX1
	JR	MAIN_LEX0
;
MAIN_LEX2:	PUSH	IY			;SAVE POINTER
MAIN_LEX3:	INC	HL
	LD	A,(HL)
	CP	160
	JP	PO,MAIN_LEX6			;FOUND
	INC	IY
	LD	A,(IY)
	CP	(HL)
	JR	NZ,MAIN_LEX7
	CP	161
	JP	PE,MAIN_LEX3
MAIN_LEX7:	LD	A,(IY)
	CP	'.'
	JR	Z,MAIN_LEX6			;FOUND (ABBREV.)
	CALL	MAIN_RANGE1
	JR	C,MAIN_LEX5
MAIN_LEX4:	POP	IY			;RESTORE POINTER
	JR	MAIN_LEX1
;
MAIN_LEX5:	LD	A,(HL)
	CP	' '
	JR	NZ,MAIN_LEX4
	DEC	IY
MAIN_LEX6:	POP	AF
	XOR	A
	LD	A,B
	RET
;
;DEL - DELETE A PROGRAM LINE.
;   Inputs: HL addresses program line.
; Destroys: B,C,F
;
MAIN_DEL:	PUSH	DE
	PUSH	HL
	PUSH	HL
	LD	B,0
	LD	C,(HL)
	ADD	HL,BC
	PUSH	HL
	EX	DE,HL
	CALL	GETTOP
	SBC	HL,DE
	LD	B,H
	LD	C,L
	POP	HL
	POP	DE
	LDIR	;DELETE LINE
	POP	HL
	POP	DE
	RET
;
;LOAD0 - LOAD A DISK FILE THEN CLEAN.
;   Inputs: Filename in ACCS (term CR)
; Destroys: A,B,C,D,E,H,L,F
;
;CLEAN - CHECK FOR BAD PROGRAM, FIND END OF TEXT
; AND WRITE FF FF.
; Destroys: A,B,C,H,L,F
;
LOAD0:	LD	DE,(PAGE)
	LD	HL,-256
	ADD	HL,SP
	SBC	HL,DE			;FIND AVAILABLE SPACE
	LD	B,H
	LD	C,L
	LD	HL,ACCS
	CALL	OSLOAD			;LOAD
	CALL	NC,MAIN_NEWIT
	LD	A,0
	JP	NC,ERROR		;"No room"
MAIN_CLEAN:	CALL	GETTOP
	DEC	HL
	LD	(HL),-1			;WRITE &FFFF
	DEC	HL
	LD	(HL),-1
	JR	CLEAR
;
GETTOP:	LD	HL,(PAGE)
	LD	B,0
	LD	A,MAIN_CR
MAIN_GETOP1:	LD	C,(HL)
	INC	C
	DEC	C
	JR	Z,MAIN_GETOP2
	ADD	HL,BC
	DEC	HL
	CP	(HL)
	INC	HL
	JR	Z,MAIN_GETOP1
	JP	MAIN_BAD
MAIN_GETOP2:	INC	HL			;N.B. CALLED FROM NEWIT
	INC	HL
	INC	HL
	RET
;
;NEWIT - NEW PROGRAM THEN CLEAR
;   Destroys: H,L
;
;CLEAR - CLEAR ALL DYNAMIC VARIABLES INCLUDING
; FUNCTION AND PROCEDURE POINTERS.
;   Destroys: Nothing
;
MAIN_NEWIT:	LD	HL,(PAGE)
	LD	(HL),0
CLEAR:	PUSH	HL
	PUSH	BC
	PUSH	AF
	CALL	GETTOP
	LD	(LOMEM),HL
	LD	(FREE),HL
	LD	HL,DYNVAR
	LD	B,2*(54+2)
MAIN_CLEAR1:	LD	(HL),0
	INC	HL
	DJNZ	MAIN_CLEAR1
	POP	AF
	POP	BC
	POP	HL
	RET
;
;LISTIT - LIST A PROGRAM LINE.
;    Inputs: HL addresses line
;            DE = line number (binary)
;	     E' = indentation count
;            IX addresses LISTON
;  Destroys: A,D,E,B',C',D',E',H',L',IY,F
;
MAIN_LISTIT:	PUSH	HL
	EX	DE,HL
	PUSH	BC
	CALL	MAIN_PBCD
	POP	BC
	POP	HL
	LD	A,(HL)
	EXX
	LD	HL,MAIN_TOKSUB
	LD	BC,MAIN_LENSUB
	CPIR
	CALL	Z,MAIN_INDSUB
	CP	MAIN_TENDCASE
	CALL	Z,MAIN_INDSUB
	LD	A,' '
	BIT	0,(IX)
	CALL	NZ,OUTCHR
	LD	A,E
	ADD	A,A
	BIT	1,(IX)
	CALL	NZ,SPACES
	EXX
	LD	A,(HL)
	LD	E,0
	EXX
	LD	BC,MAIN_LENADD
MAIN_LIST5:	LD	HL,MAIN_TOKADD
	CPIR
	CALL	Z,MAIN_INDADD
	CP	MAIN_TCASE
	CALL	Z,MAIN_INDADD
	EXX
MAIN_LIST8:	LD	A,(HL)
	INC	HL
	CP	MAIN_CR
	JR	Z,MAIN_LIST9
	LD	D,A
	CP	MAIN_TEXIT
	JR	NZ,MAIN_LIST6
	SET	7,E
MAIN_LIST6:	CP	'"'
	JR	NZ,MAIN_LIST7
	INC	E
MAIN_LIST7:	CALL	MAIN_LOUT
	LD	A,E
	AND	81H
	JR	NZ,MAIN_LIST8
	LD	A,(HL)
	EXX
	LD	HL,MAIN_TOKSUB
	LD	BC,3
	CPIR
	CALL	Z,MAIN_INDSUB
	LD	C,4
	JR	MAIN_LIST5
;
MAIN_LIST9:	LD	A,D
	CP	MAIN_TTHEN
	EXX
	CALL	Z,MAIN_INDADD
	EXX
	JR	CRLF
;
MAIN_PRLINO:	PUSH	HL
	POP	IY
	PUSH	BC
	CALL	DECODE
	POP	BC
	EXX
	PUSH	BC
	PUSH	DE
	CALL	PBCDL
	POP	DE
	POP	BC
	EXX
	PUSH	IY
	POP	HL
	RET
;
MAIN_LOUT:	BIT	0,E
	JR	NZ,OUTCHR
	CP	MAIN_TLINO
	JR	Z,MAIN_PRLINO
	CALL	OUT_
	RET
;
MAIN_INDSUB:	DEC	E
	JP	P,MAIN_INDRET
MAIN_INDADD:	INC	E
MAIN_INDRET:	RET
;
;CRLF - SEND CARRIAGE RETURN, LINE FEED.
;  Destroys: A,F
;OUTCHR - OUTPUT A CHARACTER TO CONSOLE.
;    Inputs: A = character
;  Destroys: A,F
;
CRLF:	LD	A,MAIN_CR
	CALL	OUTCHR
	LD	A,MAIN_LF
OUTCHR:	CALL	OSWRCH
	SUB	MAIN_CR
	JR	Z,MAIN_CARRET
	RET	C			;NON-PRINTING
	LD	A,(COUNT)
	INC	A
MAIN_CARRET:	LD	(COUNT),A
	RET	Z
	PUSH	HL
	LD	HL,(WIDTH)
	CP	L
	POP	HL
	RET	NZ
	JR	CRLF
;
;OUT - SEND CHARACTER OR KEYWORD
;   Inputs: A = character (>=10, <128)
;           A = Token (<10, >=128)
;  Destroys: A,F
;
OUT_:	CP	160
	JP	PE,OUTCHR
	PUSH	BC
	PUSH	HL
	LD	HL,KEYWDS
	LD	BC,KEYWDL
	CPIR
	CALL	NZ,OUTCHR
	LD	B,160
	CP	145
	JP	PE,MAIN_TOKEN1
	INC	B
MAIN_TOKEN1:	LD	A,(HL)
	INC	HL
	CP	B
	PUSH	AF
	CALL	PE,OUTCHR
	POP	AF
	JP	PE,MAIN_TOKEN1
	POP	HL
	POP	BC
	RET
;
;FINDL - FIND PROGRAM LINE.
;   Inputs: HL = line number (binary)
;  Outputs: HL addresses line (if found)
;           DE = line number
;           Z-flag set if found.
; Destroys: A,B,C,D,E,H,L,F
;
FINDL:	EX	DE,HL
	LD	HL,(PAGE)
	XOR	A			;A=0
	CP	(HL)
	INC	A
	RET	NC
	XOR	A			;CLEAR CARRY
	LD	B,A
MAIN_FINDL1:	LD	C,(HL)
	PUSH	HL
	INC	HL
	LD	A,(HL)
	INC	HL
	LD	H,(HL)
	LD	L,A
	SBC	HL,DE
	POP	HL
	RET	NC			;FOUND OR PAST
	ADD	HL,BC
	JR	MAIN_FINDL1
;
;SETLIN - Search program for line containing address.
;   Inputs: Address in (CURLIN)
;  Outputs: Line number in HL
; Destroys: B,C,D,E,H,L,F
;
SETLIN:	LD	B,0
	LD	DE,(CURLIN)
	LD	HL,(PAGE)
	OR	A
	SBC	HL,DE
	ADD	HL,DE
	JR	NC,MAIN_SET3
MAIN_SET1:	LD	C,(HL)
	INC	C
	DEC	C
	JR	Z,MAIN_SET3
	ADD	HL,BC
	SBC	HL,DE
	ADD	HL,DE
	JR	C,MAIN_SET1
	SBC	HL,BC
	INC	HL
	LD	E,(HL)			;LINE NUMBER
	INC	HL
	LD	D,(HL)
	EX	DE,HL
MAIN_SET2:	RET
;
MAIN_SET3:	LD	HL,0
	JR	MAIN_SET2
;
;SAYLN - PRINT " at line nnnn" MESSAGE.
;   Inputs: HL = line number
;  Outputs: Carry=0 if line number is zero.
;           Carry=1 if line number is non-zero.
; Destroys: A,B,C,D,E,H,L,F
;
SAYLN:	LD	A,H
	OR	L
	RET	Z
	CALL	TELL
	DEFM	' at line '
	DEFB	0
PBCDL:	LD	C,0
	JR	MAIN_PBCD0
;
;PBCD - PRINT NUMBER AS DECIMAL INTEGER.
;   Inputs: HL = number (binary).
;  Outputs: Carry = 1
; Destroys: A,B,C,D,E,H,L,F
;
MAIN_PBCD:	LD	C,' '
MAIN_PBCD0:	LD	B,5
	LD	DE,10000
MAIN_PBCD1:	XOR	A
MAIN_PBCD2:	SBC	HL,DE
	INC	A
	JR	NC,MAIN_PBCD2
	ADD	HL,DE
	DEC	A
	JR	Z,MAIN_PBCD3
	SET	4,C
	SET	5,C
MAIN_PBCD3:	OR	C
	CALL	NZ,OUTCHR
	LD	A,B
	CP	5
	JR	Z,MAIN_PBCD4
	ADD	HL,HL
	LD	D,H
	LD	E,L
	ADD	HL,HL
	ADD	HL,HL
	ADD	HL,DE
MAIN_PBCD4:	LD	DE,1000
	DJNZ	MAIN_PBCD1
	SCF
	RET
;
;HANDLE WHOLE ARRAY:
;
MAIN_GETV1:	INC	IY
	INC	IY			;SKIP ()
	PUSH	HL			;SET EXIT CONDITIONS
	POP	IX
	LD	A,D
	OR	64			;FLAG ARRAY
	CP	A
	RET
;
;PUTVAR - CREATE VARIABLE AND INITIALISE TO ZERO.
;   Inputs: HL, IY as returned from GETVAR (NZ).
;  Outputs: As GETVAR.
; Destroys: everything
;
PUTVAR:	CALL	CREATE
	LD	A,(IY)
	CP	'('
	JR	NZ,MAIN_GETVZ		;SET EXIT CONDITIONS
	LD	A,(IY+1)
	CP	')'			;WHOLE ARRAY?
	JR	Z,MAIN_GETV1
MAIN_ARRAY:	LD	A,14			;'Bad use of array'
MAIN_ERROR3:	JP	ERROR
;
;GETVAR - GET LOCATION OF VARIABLE, RETURN IN HL & IX
;   Inputs: IY addresses first character.
;  Outputs: Carry set and NZ if illegal character.
;           Z-flag set if variable found, then:
;            A = variable type (0,4,5,128 or 129)
;                (68,69 or 193 for whole array)
;            HL = IX = variable pointer.
;            IY updated
;           If Z-flag & carry reset, then:
;            HL, IY set for subsequent PUTVAR call.
; Destroys: everything
;
GETVAR:	LD	A,(IY)
	CP	'!'
	JR	Z,MAIN_GETV5
	CP	'?'
	JR	Z,MAIN_GETV6
	CP	'|'
	JR	Z,MAIN_GETVF
	CP	'$'
	JR	Z,MAIN_GETV4
	CALL	LOCATE
	RET	NZ
	LD	A,(IY)
	CP	'('			;ARRAY?
	JR	NZ,MAIN_GETVX		;EXIT
	LD	A,(IY+1)
	CP	')'			;WHOLE ARRAY?
	JR	Z,MAIN_GETV1
	PUSH	DE			;SAVE TYPE
	LD	A,(HL)
	INC	HL
	LD	H,(HL)
	LD	L,A			;INDIRECT LINK
	AND	0FEH
	OR	H
	JR	Z,MAIN_ARRAY
	LD	A,(HL)			;NO. OF DIMENSIONS
	OR	A
	JR	Z,MAIN_ARRAY
	INC	HL
	LD	DE,0			;ACCUMULATOR
	PUSH	AF
	INC	IY			;SKIP (
MAIN_GETV3:	PUSH	HL
	PUSH	DE
	CALL	EXPRI			;SUBSCRIPT
	EXX
	POP	DE
	EX	(SP),HL
	LD	C,(HL)
	INC	HL
	LD	B,(HL)
	INC	HL
	EX	(SP),HL
	EX	DE,HL
	PUSH	DE
	CALL	MUL16			;HL=HL*BC
	POP	DE
	ADD	HL,DE
	EX	DE,HL
	OR	A
	SBC	HL,BC
	LD	A,15
	JR	NC,MAIN_ERROR3		;"Subscript"
	POP	HL
	POP	AF
	DEC	A			;DIMENSION COUNTER
	JR	NZ,MAIN_GETV2
	CALL	BRAKET			;CLOSING BRACKET
	POP	AF			;RESTORE TYPE
	PUSH	HL
	CALL	X14OR5			;DE=DE*n
	POP	HL
	ADD	HL,DE
	LD	D,A			;TYPE
	LD	A,(IY)
MAIN_GETVX:	CP	'?'
	JR	Z,MAIN_GETV9
	CP	'!'
	JR	Z,MAIN_GETV8
MAIN_GETVZ:	PUSH	HL			;SET EXIT CONDITIONS
	POP	IX
	LD	A,D
	CP	A
	RET
;
MAIN_GETV2:	PUSH	AF
	CALL	COMMA
	JR	MAIN_GETV3
;
;PROCESS UNARY & BINARY INDIRECTION:
;
MAIN_GETV5:	LD	A,4			;UNARY 32-BIT INDIRN.
	JR	MAIN_GETV7
MAIN_GETV6:	XOR	A			;UNARY 8-BIT INDIRECTION
	JR	MAIN_GETV7
MAIN_GETVF:	LD	A,5			;VARIANT INDIRECTION
	JR	MAIN_GETV7
MAIN_GETV4:	LD	A,128			;STATIC STRING
MAIN_GETV7:	SBC	HL,HL
	PUSH	AF
	JR	MAIN_GETV0
;
MAIN_GETV8:	LD	B,4			;32-BIT BINARY INDIRN.
	JR	MAIN_GETVA
MAIN_GETV9:	LD	B,0			;8-BIT BINARY INDIRN.
MAIN_GETVA:	PUSH	HL
	POP	IX
	LD	A,D			;TYPE
	CP	129
	RET	Z			;STRING!
	PUSH	BC
	CALL	LOADN			;LEFT OPERAND
	CALL	SFIX
	EXX
MAIN_GETV0:	PUSH	HL
	INC	IY
	CALL	ITEMI
	EXX
	POP	DE
	POP	AF
	ADD	HL,DE
	PUSH	HL
	POP	IX
	CP	A
	RET
;
;GETDEF - Find entry for FN or PROC in dynamic area.
;   Inputs: IY addresses byte following "DEF" token.
;  Outputs: Z flag set if found
;           Carry set if neither FN or PROC first.
;           If Z: HL points to entry
;                 IY addresses delimiter
; Destroys: A,D,E,H,L,IY,F
;
GETDEF:	LD	A,(IY+1)
	CALL	MAIN_RANGE1
	RET	C
	LD	A,(IY)
	LD	HL,FNPTR
	CP	MAIN_TFN
	JR	Z,MAIN_LOC2
	LD	HL,PROPTR
	CP	MAIN_TPROC
	JR	Z,MAIN_LOC2
	SCF
	RET
;
;LOCATE - Try to locate variable name in static or
;dynamic variables.  If illegal first character return
;carry, non-zero.  If found, return no-carry, zero.
;If not found, return no-carry, non-zero.
;   Inputs: IY addresses first character of name.
;           A=(IY)
;  Outputs: Z-flag set if found, then:
;            IY addresses terminator
;            HL addresses location of variable
;            D=type of variable:  4 = integer
;                                 5 = floating point
;                               129 = string
; Destroys: A,D,E,H,L,IY,F
;
LOCATE:	SUB	'@'
	RET	C
	LD	H,0
	CP	'Z'-'@'+1
	JR	NC,MAIN_LOC0			;NOT STATIC
	ADD	A,A
	LD	L,A
	LD	A,(IY+1)		;2nd CHARACTER
	CP	'%'
	JR	NZ,MAIN_LOC1			;NOT STATIC
	LD	A,(IY+2)
	CP	'('
	JR	Z,MAIN_LOC1			;NOT STATIC
	ADD	HL,HL
	LD	DE,STAVAR		;STATIC VARIABLES
	ADD	HL,DE
	INC	IY
	INC	IY
	LD	D,4			;INTEGER TYPE
	XOR	A
	RET
;
MAIN_LOC0:	CP	'_'-'@'
	RET	C
	CP	'z'-'@'+1
	CCF
	DEC	A			;SET NZ
	RET	C
	SUB	3
	ADD	A,A
	LD	L,A
MAIN_LOC1:	LD	DE,DYNVAR		;DYNAMIC VARIABLES
	DEC	L
	DEC	L
	SCF
	RET	M
	ADD	HL,DE
MAIN_LOC2:	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	LD	A,D
	OR	E
	JR	Z,MAIN_LOC6			;UNDEFINED VARIABLE
	LD	H,D
	LD	L,E
	INC	HL			;SKIP LINK
	INC	HL
	PUSH	IY
MAIN_LOC3:	LD	A,(HL)			;COMPARE
	INC	HL
	INC	IY
	CP	(IY)
	JR	Z,MAIN_LOC3
	OR	A			;0=TERMINATOR
	JR	Z,MAIN_LOC5			;FOUND (MAYBE)
MAIN_LOC4:	POP	IY
	EX	DE,HL
	JR	MAIN_LOC2			;TRY NEXT ENTRY
;
MAIN_LOC5:	DEC	IY
	LD	A,(IY)
	CP	'('
	JR	Z,MAIN_LOCX			;FOUND
	INC	IY
	CALL	RANGE
	JR	C,MAIN_LOCX			;FOUND
	CP	'('
	JR	Z,MAIN_LOC4			;KEEP LOOKING
	LD	A,(IY-1)
	CALL	MAIN_RANGE1
	JR	NC,MAIN_LOC4			;KEEP LOOKING
MAIN_LOCX:	POP	DE
MAIN_TYPE:	LD	A,(IY-1)
	CP	'$'
	LD	D,129
	RET	Z			;STRING
	CP	'&'
	LD	D,1
	RET	Z			;BYTE
	CP	'%'
	LD	D,4
	RET	Z			;INTEGER
	INC	D
	CP	A
	RET
;
MAIN_LOC6:	INC	A			;SET NZ
	RET
;
;CREATE - CREATE NEW ENTRY, INITIALISE TO ZERO.
;   Inputs: HL, IY as returned from LOCATE (NZ).
;  Outputs: As LOCATE, GETDEF.
; Destroys: As LOCATE, GETDEF.
;
CREATE:	XOR	A
	LD	DE,(FREE)
	LD	(HL),D
	DEC	HL
	LD	(HL),E
	EX	DE,HL
	LD	(HL),A
	INC	HL
	LD	(HL),A
	INC	HL
MAIN_LOC7:	INC	IY
	CALL	RANGE			;END OF VARIABLE?
	JR	C,MAIN_LOC8
	LD	(HL),A
	INC	HL
	CALL	MAIN_RANGE1
	JR	NC,MAIN_LOC7
	CP	'('
	JR	Z,MAIN_LOC8
	LD	A,(IY+1)
	CP	'('
	JR	Z,MAIN_LOC7
	INC	IY
MAIN_LOC8:	LD	(HL),0			;TERMINATOR
	INC	HL
	PUSH	HL
	CALL	MAIN_TYPE
	LD	A,(IY)
	CP	'('
	LD	A,2			;SIZE OF INDIRECT LINK
	JR	Z,MAIN_LOC9
	LD	A,D
	OR	A			;STRING?
	JP	P,MAIN_LOC9
	LD	A,4
MAIN_LOC9:	LD	(HL),0			;INITIALISE TO ZERO
	INC	HL
	DEC	A
	JR	NZ,MAIN_LOC9
	LD	(FREE),HL
	CALL	CHECK
	POP	HL
	XOR	A
	RET
;
;LINNUM - GET LINE NUMBER FROM TEXT STRING
;   Inputs: IY = Text Pointer
;  Outputs: HL = Line number (zero if none)
;           IY updated
; Destroys: A,D,E,H,L,IY,F
;
MAIN_LINNUM:	CALL	NXT
	LD	HL,0
MAIN_LINNM1:	LD	A,(IY)
	SUB	'0'
	RET	C
	CP	10
	RET	NC
	INC	IY
	LD	D,H
	LD	E,L
	ADD	HL,HL			;*2
	JR	C,MAIN_TOOBIG
	ADD	HL,HL			;*4
	JR	C,MAIN_TOOBIG
	ADD	HL,DE			;*5
	JR	C,MAIN_TOOBIG
	ADD	HL,HL			;*10
	JR	C,MAIN_TOOBIG
	LD	E,A
	LD	D,0
	ADD	HL,DE			;ADD IN DIGIT
	JR	NC,MAIN_LINNM1	
MAIN_TOOBIG:	LD	A,20
	JP	ERROR			;"Too big"
;
;PAIR - GET PAIR OF LINE NUMBERS FOR RENUMBER/AUTO.
;   Inputs: IY = text pointer
;  Outputs: HL = first number (10 by default)
;           BC = second number (10 by default)
; Destroys: A,B,C,D,E,H,L,B',C',D',E',H',L',IY,F
;
MAIN_PAIR:	CALL	MAIN_LINNUM			;FIRST
	LD	A,H
	OR	L
	JR	NZ,MAIN_PAIR1
	LD	L,10
MAIN_PAIR1:	CALL	TERMQ
	INC	IY
	PUSH	HL
	LD	HL,10
	CALL	NZ,MAIN_LINNUM		;SECOND
	EX	(SP),HL
	POP	BC
	LD	A,B
	OR	C
	RET	NZ
	CALL	EXTERR
	DEFM	'Silly'
	DEFB	0
;
;DLPAIR - GET PAIR OF LINE NUMBERS FOR DELETE/LIST.
;   Inputs: IY = text pointer
;  Outputs: HL = points to program text
;           BC = second number (0 by default)
; Destroys: A,B,C,D,E,H,L,IY,F
;
MAIN_DLPAIR:	CALL	MAIN_LINNUM
	PUSH	HL
	CALL	TERMQ
	JR	Z,MAIN_DLP1
	CP	MAIN_TIF
	JR	Z,MAIN_DLP1
	INC	IY
	CALL	MAIN_LINNUM
MAIN_DLP1:	EX	(SP),HL
	CALL	FINDL
	POP	BC
	RET
;
;TEST FOR VALID CHARACTER IN VARIABLE NAME:
;   Inputs: IY addresses character
;  Outputs: Carry set if out-of-range.
; Destroys: A,F
;
RANGE:	LD	A,(IY)
	CP	'$'
	RET	C
	CP	'&'+1
	CCF
	RET	NC
	CP	'('
	RET	Z
MAIN_RANGE1:	CP	'0'
	RET	C
	CP	'9'+1
	CCF
	RET	NC
	CP	'@'			;V2.4
	RET	Z
MAIN_RANGE2:	CP	'A'
	RET	C
	CP	'Z'+1
	CCF
	RET	NC
	CP	'_'
	RET	C
	CP	'z'+1
	CCF
	RET
;
;LEXAN - LEXICAL ANALYSIS.
;  Bit 0,C: 1=left, 0=right
;  Bit 3,C: 1=in HEX
;  Bit 4,C: 1=accept line number
;  Bit 5,C: 1=in variable, FN, PROC
;  Bit 6,C: 1=in REM, DATA, *
;  Bit 7,C: 1=in quotes
;   Inputs: IY addresses source string
;           DE addresses destination string
;           (must be page boundary)
;           C  sets initial mode
;  Outputs: DE, IY updated
;           A holds carriage return
;
MAIN_LEXAN1:	LD	(DE),A			;TRANSFER TO BUFFER
	INC	DE			;INCREMENT POINTERS
	INC	IY
LEXAN2:	LD	A,E			;MAIN ENTRY
	CP	252			;TEST LENGTH
	LD	A,19
	JP	NC,ERROR		;'String too long'
	LD	A,(IY)
	CP	MAIN_CR
	RET	Z			;END OF LINE
	CALL	MAIN_RANGE1
	JR	NC,MAIN_LEXAN3
	RES	5,C			;NOT IN VARIABLE
	RES	3,C			;NOT IN HEX
MAIN_LEXAN3:	CP	' '
	JR	Z,MAIN_LEXAN1		;PASS SPACES
	CP	','
	JR	Z,MAIN_LEXAN1		;PASS COMMAS
	CP	'G'
	JR	C,MAIN_LEXAN4
	RES	3,C			;NOT IN HEX
MAIN_LEXAN4:	CP	'"'
	JR	NZ,MAIN_LEXAN5
	RL	C
	CCF	;TOGGLE C7
	RR	C
MAIN_LEXAN5:	BIT	4,C
	JR	Z,MAIN_LEXAN6
	RES	4,C
	PUSH	BC
	PUSH	DE
	CALL	MAIN_LINNUM			;GET LINE NUMBER
	POP	DE
	POP	BC
	LD	A,H
	OR	L
	CALL	NZ,MAIN_ENCODE		;ENCODE LINE NUMBER
	JR	LEXAN2			;CONTINUE
;
MAIN_LEXAN6:	DEC	C
	JR	Z,MAIN_LEXAN7		;C=1 (LEFT)
	INC	C
	JR	NZ,MAIN_LEXAN1
	OR	A
	CALL	P,MAIN_LEX			;TOKENISE IF POSS.
	JR	MAIN_LEXAN8
;
MAIN_LEXAN7:	CP	'*'
	JR	Z,MAIN_LEXAN9
	OR	A
	CALL	P,MAIN_LEX			;TOKENISE IF POSS.
	CP	MAIN_TDATA
	JR	Z,MAIN_LEXAN9
	CP	MAIN_TOKLO
	JR	C,MAIN_LEXAN8
	CP	MAIN_TOKHI+1
	JR	NC,MAIN_LEXAN8
	ADD	A,MAIN_OFFSET		;LEFT VERSION
MAIN_LEXAN8:	CP	MAIN_TREM
	JR	NZ,MAIN_LEXANA
MAIN_LEXAN9:	SET	6,C			;QUIT TOKENISING
MAIN_LEXANA:	CP	MAIN_TFN
	JR	Z,MAIN_LEXANB
	CP	MAIN_TPROC
	JR	Z,MAIN_LEXANB
	CALL	MAIN_RANGE2
	JR	C,MAIN_LEXANC
MAIN_LEXANB:	SET	5,C			;IN VARIABLE/FN/PROC
MAIN_LEXANC:	CP	'&'
	JR	NZ,MAIN_LEXAND
	SET	3,C			;IN HEX
MAIN_LEXAND:	LD	HL,MAIN_LIST1
	PUSH	BC
	LD	BC,MAIN_LIST1L
	CPIR
	POP	BC
	JR	NZ,MAIN_LEXANE
	SET	4,C			;ACCEPT LINE NUMBER
MAIN_LEXANE:	LD	HL,MAIN_LIST2
	PUSH	BC
	LD	BC,MAIN_LIST2L
	CPIR
	POP	BC
	JR	NZ,MAIN_LEXANF
	SET	0,C			;ENTER LEFT MODE
MAIN_LEXANF:	JP	MAIN_LEXAN1
;
MAIN_LIST1:	DEFB	MAIN_TGOTO
	DEFB	MAIN_TGOSUB
	DEFB	MAIN_TRESTORE
	DEFB	MAIN_TTRACE
MAIN_LIST2:	DEFB	MAIN_TTHEN
	DEFB	MAIN_TELSE
MAIN_LIST1L:	EQU	$-MAIN_LIST1
	DEFB	MAIN_TREPEAT
	DEFB	MAIN_TERROR
	DEFB	':'
MAIN_LIST2L:	EQU	$-MAIN_LIST2
;
;ENCODE - ENCODE LINE NUMBER INTO PSEUDO-BINARY FORM.
;   Inputs: HL=line number, DE=string pointer
;  Outputs: DE updated, BIT 4,C set.
; Destroys: A,B,C,D,E,H,L,F
;
MAIN_ENCODE:	SET	4,C
	EX	DE,HL
	LD	(HL),MAIN_TLINO
	INC	HL
	LD	A,D
	AND	0C0H
	RRCA
	RRCA
	LD	B,A
	LD	A,E
	AND	0C0H
	OR	B
	RRCA
	RRCA
	XOR	01010100B
	LD	(HL),A
	INC	HL
	LD	A,E
	AND	3FH
	OR	'@'
	LD	(HL),A
	INC	HL
	LD	A,D
	AND	3FH
	OR	'@'
	LD	(HL),A
	INC	HL
	EX	DE,HL
	RET
;
;TEXT - OUTPUT MESSAGE.
;   Inputs: HL addresses text (terminated by nul)
;  Outputs: HL addresses character following nul.
; Destroys: A,H,L,F
;
REPORT:	LD	HL,(ERRTXT)
MAIN_TEXT:	LD	A,(HL)
	INC	HL
	OR	A
	RET	Z
	CP	MAIN_LF
	JR	Z,MAIN_TEXTLF		;Token for TINT
	CALL	OUT_
	JR	MAIN_TEXT
;
MAIN_TEXTLF:	CALL	OUTCHR
	JR	MAIN_TEXT
;
;TELL - OUTPUT MESSAGE.
;   Inputs: Text follows subroutine call (term=nul)
; Destroys: A,F
;
TELL:	EX	(SP),HL			;GET RETURN ADDRESS
	CALL	MAIN_TEXT
	EX	(SP),HL
	RET
;
; NLIST - Check for end of list
;
NLIST:	CALL	NXT
	CP	','			;ANOTHER VARIABLE?
	JR	Z,MAIN_NXT1
	POP	BC			;DITCH RETURN ADDRESS
	JP	XEQ
;
NXT:	LD	A,(IY)
	CP	' '
	RET	NZ
MAIN_NXT1:	INC	IY
	JR	NXT
;

